import React from "react";
import "./EmployeeProfile.css";

/**
 * Props:
 * - image: string (image URL)
 * - name: string
 * - email: string
 * - biography: string
 */



export default function EmployeeProfile({
  image,
  name,
  email,
  biography,
  website, // optional
  website2 // optional
}) {
  return (
    <div className="employee-card">
      <div className="employee-header">
        <div className="employee-image-wrapper">
          <img src={image} alt={name} className="employee-image" />
        </div>

        <div className="employee-info">
          <h2 className="employee-name">{name}</h2>

          <a href={`mailto:${email}`} className="employee-email">
           📧 {email}
          </a>

          {website && (
            <a
              href={website}
              className="employee-website"
              target="_blank"
              rel="noopener noreferrer"
            >
             🌐 {website}
            </a>
          )}
 	{website2 && (
            <a
              href={website2}
              className="employee-website"
              target="_blank"
              rel="noopener noreferrer"
            >
             🌐 {website2}
            </a>
          )}
        </div>
      </div>

      <div className="employee-bio">
        {biography}
      </div>
    </div>
  );
}
