import * as React from "react"
import { withPrefix } from "gatsby"
import Layout from "../components/Layout"
import EmployeeProfile from "../components/EmployeeProfile"
import BreadCrumb from "../components/BreadCrumb"
import Seo from "../components/seo"
import CHRISTIAN_IMG from "../images/christian.jpg";
const FLAG_EN = '\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}'
const FLAG_CZ = '\u{1F1E8}\u{1F1FF}';
const christian_languages = FLAG_EN + " " + FLAG_CZ;
const christian_website = "https://github.com/lacdael"
const christian_website2 = "https://www.youtube.com/@try-restart"
const christian_bio = `Based in East Anglia, I am an embedded software engineer specialising in control systems, with a particular interest in smart agriculture technologies. I have extensive experience working with CAN bus standards, including ISO 11783 and SAE J1939, as well as developing real-time systems using FreeRTOS.`

const get_in_touch = "Open to consulting, technical partnerships, and prototype development projects with East Anglians. If you are working on embedded systems, control applications, or smart agriculture technologies and would like to collaborate, please get in touch."



const HomePage = () => {
  return (
    <Layout>
      <BreadCrumb links={[ "/"]} titles={["Home","Contact"]} />
      <EmployeeProfile
	  image={ CHRISTIAN_IMG }
	  name="Christian Lacdael"
	  email="c.lacdael@poetry.me.uk"
	  website={ christian_website }
	  website2={ christian_website2 }
	  biography={christian_bio} />

	  <br/>
    <hr/>
	  <br/>
    <p>{ get_in_touch }</p>
    </Layout>
  )
}

export default HomePage

export function Head({ location }) {
  const siteUrl = "https://lacdael.github.io"
  const siteRoot = `${siteUrl}${withPrefix("/")}`
  const contactUrl = `${siteRoot}contact/`
  const profileImage = `${siteRoot}christian.jpg`
  const description =
    "Christian Lacdael is an embedded software engineer specialising in control systems, real-time systems and smart agriculture technologies."

  const schema = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Person",
        "@id": `${contactUrl}#person`,
        name: "Christian Lacdael",
        givenName: "Christian",
        familyName: "Lacdael",
        description,
        image: { "@type": "ImageObject", url: profileImage },
        jobTitle: "Embedded Software Engineer",
        url: contactUrl,
        sameAs: [christian_website, christian_website2],
        worksFor: {
          "@type": "Organization",
          name: "Wisdel.uk",
          url: siteRoot,
        },
        address: { "@type": "PostalAddress", addressCountry: "GB" },
      },
      {
        "@type": "WebPage",
        "@id": `${contactUrl}#webpage`,
        url: contactUrl,
        name: "Contact Christian Lacdael | Wisdel.uk",
        description,
        inLanguage: "en-GB",
        about: { "@id": `${contactUrl}#person` },
        isPartOf: { "@id": `${siteRoot}#website` },
      },
      {
        "@type": "WebSite",
        "@id": `${siteRoot}#website`,
        url: siteRoot,
        name: "Wisdel.uk",
        inLanguage: "en-GB",
        publisher: { "@id": `${contactUrl}#person` },
      },
    ],
  }

  return (
    <Seo
      title="Contact Christian Lacdael"
      description={description}
      image={withPrefix("/christian.jpg")}
      imageAlt="Christian Lacdael, embedded software engineer"
      what="profile"
      schemaMarkup={schema}
      pathname={location.pathname}
    />
  )
}
